import { action } from "solid-js";
const go = (cb) => { void action(function* () { if (typeof cb === "function") cb(); })(); };
class T extends EventTarget { dispatchEvent(e) { go(); return true; } }
export const makeTarget = () => new T();
export const makeMap = () => { const m = new Map(); m.forEach = (cb) => go(cb); return m; };
